#include <bits/stdc++.h>
using namespace std;

#define N 100000
#define D 130
#define MOD 998244353
#define rep(i, n) for(int i = 0; i < n; ++i)
#define pil pair<int, long long>

vector<int>e[N];
bool used[N];
int a[N];
long long ans;

int gcd(int x, int y) {
	if (x > y)swap(x, y);
	if (x == 0)return y;
	return gcd(y%x, x);
}

vector<pair<int, pil> > dfs(int k) {
	used[k] = true;
	vector<pair<int, pil> > list1, list2;
	int idx[D];
	int g;
	long long x, y, z;
	list1.push_back({ a[k],{1,1LL} });
	int sz = e[k].size();
	int sz1, sz2, defalut_sz;
	rep(ii, sz) {
		if (!used[e[k][ii]]) {

			list2 = dfs(e[k][ii]);
			sz1 = list1.size();
			sz2 = list2.size();
			defalut_sz = sz1;

			rep(j, sz2) {
				idx[j] = -1;
				rep(i, sz1) {
					if (i < defalut_sz) {
						g = gcd(list1[i].first, list2[j].first);
						if (i == 0)list2[j].first = g;
						x = (list1[i].second.second*list2[j].second.first) % MOD;
						y = (list2[j].second.second*list1[i].second.first) % MOD;
						z = ((x + y)*g) % MOD;
						ans = (ans + z) % MOD;
					}					
					if (list1[i].first == list2[j].first)idx[j] = i;
				}
				if (idx[j] == -1) {
					idx[j] = sz1;
					list1.push_back({ list2[j].first,{0,0LL} });
					sz1++;
				}
			}

			rep(j, sz2) {
				list1[idx[j]].second.first += list2[j].second.first;
				list1[idx[j]].second.second += list2[j].second.first + list2[j].second.second;
				if (list1[idx[j]].second.second >= MOD)list1[idx[j]].second.second -= MOD;
			}

		}
	}
	return list1;
}

int main() {
	int n, x, y;
	cin >> n;
	rep(i, n)cin >> a[i];
	rep(i, n - 1) {
		cin >> x >> y;
		e[x - 1].push_back(y - 1);
		e[y - 1].push_back(x - 1);
	}
	ans = 0;
	rep(i, n)used[i] = false;
	dfs(0);
	cout << ans << endl;
	return 0;
}
